import{_ as e,o as t,c as s,a4 as i}from"./chunks/framework.BBs01uty.js";const u=JSON.parse('{"title":"阶段 7：12306 微服务进阶（可选）","description":"","frontmatter":{},"headers":[],"relativePath":"java-practice/07-microservice-12306.md","filePath":"java-practice/07-microservice-12306.md"}'),n={name:"java-practice/07-microservice-12306.md"};function l(r,a,o,p,d,c){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="阶段-7-12306-微服务进阶-可选" tabindex="-1">阶段 7：12306 微服务进阶（可选） <a class="header-anchor" href="#阶段-7-12306-微服务进阶-可选" aria-label="Permalink to &quot;阶段 7：12306 微服务进阶（可选）&quot;">​</a></h1><blockquote><p><strong>目标</strong>：从单体到微服务——理解服务拆分、网关、注册中心、分布式锁，看懂企业级高并发项目长什么样。<strong>可选阶段</strong>，建议在阶段 6 完成后再进入。</p><p><strong>前置</strong>：阶段 1-6 完成（单体已能独立开发）。项目在 <code>~/Documents/Jun/code/12306</code>。</p></blockquote><h2 id="一、验收标准-做完自检" tabindex="-1">一、验收标准（做完自检） <a class="header-anchor" href="#一、验收标准-做完自检" aria-label="Permalink to &quot;一、验收标准（做完自检）&quot;">​</a></h2><ul><li>[ ] 能说出 12306 拆成了哪些服务、每个服务干什么</li><li>[ ] 能对比 mall（单体）和 12306（微服务）在架构上的 3 个关键差异</li><li>[ ] 能说出&quot;买票&quot;这条业务跨了哪几个服务、数据怎么流转</li><li>[ ] 理解网关、注册中心、分布式锁各自解决什么问题</li></ul><h2 id="二、12306-项目结构" tabindex="-1">二、12306 项目结构 <a class="header-anchor" href="#二、12306-项目结构" aria-label="Permalink to &quot;二、12306 项目结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12306/</span></span>
<span class="line"><span>├── services/                  # 微服务（按业务拆分）</span></span>
<span class="line"><span>│   ├── gateway-service        # 网关：所有请求的统一入口</span></span>
<span class="line"><span>│   ├── user-service           # 用户/乘车人（注册、登录、证件管理）</span></span>
<span class="line"><span>│   ├── ticket-service         # 购票（余票查询、选座、下单）</span></span>
<span class="line"><span>│   ├── order-service          # 订单</span></span>
<span class="line"><span>│   ├── pay-service            # 支付</span></span>
<span class="line"><span>│   └── aggregation-service    # 聚合服务（BFF，组装多服务数据）</span></span>
<span class="line"><span>├── frameworks/                # 基础框架（公共能力，被各服务引用）</span></span>
<span class="line"><span>│   ├── cache/                 # 缓存封装（Redis）</span></span>
<span class="line"><span>│   ├── distributedid/         # 分布式 ID 生成（分库分表/订单号）</span></span>
<span class="line"><span>│   ├── idempotent/            # 幂等（防重复下单）</span></span>
<span class="line"><span>│   ├── database/              # 数据访问（含分库分表）</span></span>
<span class="line"><span>│   ├── log/ designpattern/ web/ ...</span></span>
<span class="line"><span>└── console-vue                # 管理后台前端</span></span></code></pre></div><p>技术栈：JDK 17 + SpringBoot 3 + SpringCloud（Alibaba 体系：Nacos 注册中心、Sentinel 限流）+ Redis + RocketMQ + 分库分表。</p><h2 id="三、和-mall-的对比-先建立坐标系" tabindex="-1">三、和 mall 的对比（先建立坐标系） <a class="header-anchor" href="#三、和-mall-的对比-先建立坐标系" aria-label="Permalink to &quot;三、和 mall 的对比（先建立坐标系）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>mall（单体）</th><th>12306（微服务）</th></tr></thead><tbody><tr><td>部署</td><td>一个应用打成一个 jar</td><td>每个服务独立部署、独立扩缩容</td></tr><tr><td>服务间调用</td><td>进程内直接调方法</td><td>HTTP/RPC 跨进程调用（Feign 等）</td></tr><tr><td>找服务</td><td>不需要</td><td>注册中心（Nacos），服务名寻址</td></tr><tr><td>流量入口</td><td>直接访问</td><td>网关统一入口（鉴权、限流、路由）</td></tr><tr><td>事务</td><td>本地事务 @Transactional</td><td>分布式事务（更复杂，常靠&quot;最终一致性&quot;）</td></tr><tr><td>数据</td><td>一个数据库</td><td>每个服务独立库（分库分表）</td></tr></tbody></table><h2 id="四、操作步骤" tabindex="-1">四、操作步骤 <a class="header-anchor" href="#四、操作步骤" aria-label="Permalink to &quot;四、操作步骤&quot;">​</a></h2><h3 id="step-1-读官方文档建立全局认知" tabindex="-1">Step 1：读官方文档建立全局认知 <a class="header-anchor" href="#step-1-读官方文档建立全局认知" aria-label="Permalink to &quot;Step 1：读官方文档建立全局认知&quot;">​</a></h3><p>12306 项目有完整文档站：<strong><a href="https://nageoffer.com/12306" target="_blank" rel="noreferrer">https://nageoffer.com/12306</a></strong></p><p>优先读这几篇：</p><ul><li>技术架构选型</li><li>项目依赖中间件环境搭建（想跑起来必读）</li><li>分库分表方案（user-service 为什么分表）</li></ul><h3 id="step-2-读-买票-这条业务链路-核心" tabindex="-1">Step 2：读&quot;买票&quot;这条业务链路（核心） <a class="header-anchor" href="#step-2-读-买票-这条业务链路-核心" aria-label="Permalink to &quot;Step 2：读&quot;买票&quot;这条业务链路（核心）&quot;">​</a></h3><p>打开 <code>ticket-service</code> 和 <code>order-service</code>，跟着业务走一遍：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[用户查询余票&lt;br&gt;gateway] --&gt; B[ticket-service&lt;br&gt;余票缓存+选座算法]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C[用户下单&lt;br&gt;gateway] --&gt; D[ticket-service&lt;br&gt;锁座位]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E[order-service&lt;br&gt;创建订单]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; F[pay-service&lt;br&gt;支付回调]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt; E</span></span></code></pre></div><p>重点读这几个&quot;高并发关键设计&quot;：</p><ul><li><strong>余票查询</strong>：为什么查余票走 Redis 缓存而不是直接查库？（对比 mall 阶段 4）</li><li><strong>选座/锁座</strong>：两个乘车人买票，座位怎么分配、怎么防止超卖（对比秒杀场景）</li><li><strong>幂等</strong>：<code>frameworks/idempotent</code>，为什么重复点击下单不会创建两个订单</li><li><strong>分布式 ID</strong>：<code>frameworks/distributedid</code>，订单号为什么要全局唯一且有序</li></ul><h3 id="step-3-读一个服务的最小闭环" tabindex="-1">Step 3：读一个服务的最小闭环 <a class="header-anchor" href="#step-3-读一个服务的最小闭环" aria-label="Permalink to &quot;Step 3：读一个服务的最小闭环&quot;">​</a></h3><p>挑 <code>user-service</code>，模仿 mall 阶段 1 的方法：</p><ol><li>找到 Controller（<code>UserController</code> 之类）</li><li>跟到 Service 层</li><li>注意它和 mall 不同的地方：<strong>不直接查库这么简单</strong>，有分库分表、缓存、分布式锁</li></ol><h3 id="step-4-选做-尝试本地启动" tabindex="-1">Step 4（选做）：尝试本地启动 <a class="header-anchor" href="#step-4-选做-尝试本地启动" aria-label="Permalink to &quot;Step 4（选做）：尝试本地启动&quot;">​</a></h3><p>按文档站&quot;中间件环境搭建&quot;装 Nacos、Redis 等，然后启动 <code>user-service</code> 或 <code>gateway-service</code>。<strong>这一步比较耗时</strong>，如果只想学架构可以跳过，只看代码。</p><h2 id="五、动手任务" tabindex="-1">五、动手任务 <a class="header-anchor" href="#五、动手任务" aria-label="Permalink to &quot;五、动手任务&quot;">​</a></h2><ol><li>画出&quot;查余票&quot;和&quot;下单&quot;两条业务链路图（服务间调用关系）</li><li>读完 <code>frameworks/idempotent</code>，用 3 句话解释它怎么防重复下单（对比 mall 阶段 3 的事务思路）</li><li>对比总结：同是&quot;下单&quot;，mall 的下单和 12306 的下单在实现上有哪些不同</li></ol><h2 id="六、面试价值" tabindex="-1">六、面试价值 <a class="header-anchor" href="#六、面试价值" aria-label="Permalink to &quot;六、面试价值&quot;">​</a></h2><p>12306 是面试加分项目。把下面三个点讲清楚，比背八股有用得多：</p><ol><li><strong>怎么防超卖/锁座位</strong>（分布式锁 + Redis）</li><li><strong>怎么防重复下单</strong>（幂等设计）</li><li><strong>分库分表怎么分</strong>（选什么字段做分片键、读扩散怎么解决）</li></ol><h2 id="七、关联理论" tabindex="-1">七、关联理论 <a class="header-anchor" href="#七、关联理论" aria-label="Permalink to &quot;七、关联理论&quot;">​</a></h2><ul><li><a href="/knowledge/service/spring-cloud.html">Spring Cloud 微服务</a> — 注册中心、网关、Feign</li><li><a href="/knowledge/service/distributed-basics.html">分布式基础</a> — CAP、分布式事务、分布式锁</li><li><a href="/knowledge/service/mq-intro.html">消息队列</a> — 异步、削峰填谷在购票场景的落地</li></ul>`,31)])])}const g=e(n,[["render",l]]);export{u as __pageData,g as default};
